CREATE TABLE "golden"."orders" (
    "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
    "customer_id" integer NOT NULL,
    "total" numeric(12,2) DEFAULT 0 NOT NULL,
    "status" text DEFAULT 'new'::text NOT NULL,
    "total_with_tax" numeric(12,2) GENERATED ALWAYS AS ((total * 1.2)) STORED,
    CONSTRAINT "orders_customer_id_fkey" FOREIGN KEY (customer_id) REFERENCES golden.customers(id) ON DELETE CASCADE,
    CONSTRAINT "orders_pkey" PRIMARY KEY (id)
);

CREATE INDEX "orders_customer_idx" ON "golden"."orders" USING btree ("customer_id");

CREATE UNIQUE INDEX "orders_status_partial_idx" ON "golden"."orders" USING btree ("customer_id", "status");

CREATE OR REPLACE PROCEDURE golden.reset_status(IN target text)
 LANGUAGE sql
AS $procedure$ UPDATE golden.orders SET status = target $procedure$;
